// Package schema holds the gameWE database schema, compiled into the
// binary: the tables (schema.sql), the reference data (seed.sql) and the
// rights of the web users (grants.sql), for MariaDB / MySQL (mysql/) and
// PostgreSQL (postgres/, generated by tools/schemagen). The collector never
// reads SQL files from the disk; `gamewe db migrate` (internal/database)
// creates and upgrades a database from these files.
package schema

import (
	"embed"
	"fmt"
	"regexp"
	"strings"
	"sync"
)

// Dialects, the same values as config.MySQL and config.Postgres.
const (
	MySQL    = "mysql"
	Postgres = "postgres"
)

//go:embed mysql/schema.sql mysql/seed.sql mysql/grants.sql postgres/schema.sql postgres/seed.sql postgres/grants.sql
var files embed.FS

func file(dialect, name string) string {
	if dialect != Postgres {
		dialect = MySQL
	}
	b, err := files.ReadFile(dialect + "/" + name)
	if err != nil {
		panic(err) // embedded: cannot happen
	}
	return string(b)
}

// Schema returns the CREATE TABLE (and on PostgreSQL CREATE INDEX)
// statements of a new database.
func Schema(dialect string) string { return file(dialect, "schema.sql") }

// Seed returns the reference data (games, teams, actions, weapons, awards,
// ranks, options). Every statement only adds missing rows.
func Seed(dialect string) string { return file(dialect, "seed.sql") }

// Grants returns the table and column rights of the web users.
func Grants(dialect string) string { return file(dialect, "grants.sql") }

// Table is a table of the schema.
type Table struct {
	Name    string // as written in the schema (mixed case)
	Create  string // the CREATE TABLE statement (MySQL: with its keys)
	Columns []Column
	Indexes []Index
}

// Column is a column of a table.
type Column struct {
	Name string
	Def  string // the definition after the name: type, NULL, default, ...
}

// Index is an index of a table.
type Index struct {
	// Name as the database reports it: the key name on MySQL (PRIMARY for
	// the primary key), <table>_<key> in lower case on PostgreSQL.
	Name    string
	Columns []string
	Primary bool
	Unique  bool
	// Def is the key clause for ALTER TABLE ... ADD on MySQL
	// ("KEY `map` (`map`)"), the CREATE INDEX statement on PostgreSQL.
	Def string
}

var (
	parsed = map[string]func() ([]Table, error){
		MySQL:    sync.OnceValues(func() ([]Table, error) { return parseMySQL(Schema(MySQL)) }),
		Postgres: sync.OnceValues(func() ([]Table, error) { return parsePostgres(Schema(Postgres)) }),
	}
)

// Tables returns the tables of the schema in file order.
func Tables(dialect string) ([]Table, error) {
	if dialect != Postgres {
		dialect = MySQL
	}
	return parsed[dialect]()
}

var (
	reMyCreate = regexp.MustCompile("^CREATE TABLE `([^`]+)` \\($")
	reMyCol    = regexp.MustCompile("^  `([^`]+)` (.*?),?$")
	reMyKey    = regexp.MustCompile("^  ((PRIMARY KEY)|UNIQUE KEY `([^`]+)`|KEY `([^`]+)`) \\((.*?)\\)( USING \\w+)?,?$")
	reMyEnd    = regexp.MustCompile("^\\) ENGINE=")
	reKeyCol   = regexp.MustCompile("`([^`]+)`(\\(\\d+\\))?")
)

// parseMySQL reads the CREATE TABLE statements of a mariadb-dump.
func parseMySQL(sql string) ([]Table, error) {
	var tables []Table
	var t *Table
	var create []string
	for _, line := range strings.Split(sql, "\n") {
		if m := reMyCreate.FindStringSubmatch(line); m != nil {
			tables = append(tables, Table{Name: m[1]})
			t, create = &tables[len(tables)-1], []string{line}
			continue
		}
		if t == nil {
			continue
		}
		create = append(create, line)
		switch m := reMyKey.FindStringSubmatch(line); {
		case reMyEnd.MatchString(line):
			t.Create = strings.TrimSuffix(strings.Join(create, "\n"), ";")
			t = nil
		case m != nil:
			ix := Index{Primary: m[2] != "", Unique: m[3] != "", Def: strings.TrimSuffix(strings.TrimSpace(line), ",")}
			switch {
			case ix.Primary:
				ix.Name = "PRIMARY"
			case ix.Unique:
				ix.Name = m[3]
			default:
				ix.Name = m[4]
			}
			for _, k := range reKeyCol.FindAllStringSubmatch(m[5], -1) {
				ix.Columns = append(ix.Columns, k[1])
			}
			t.Indexes = append(t.Indexes, ix)
		default:
			c := reMyCol.FindStringSubmatch(line)
			if c == nil {
				return nil, fmt.Errorf("schema: table %s: cannot parse %q", t.Name, line)
			}
			t.Columns = append(t.Columns, Column{Name: c[1], Def: c[2]})
		}
	}
	if t != nil {
		return nil, fmt.Errorf("schema: table %s is not closed", t.Name)
	}
	return tables, nil
}

var (
	rePgCreate = regexp.MustCompile(`^CREATE (?:UNLOGGED )?TABLE (\w+) \($`)
	rePgCol    = regexp.MustCompile(`^  (\w+) (.*?),?$`)
	rePgPK     = regexp.MustCompile(`^  PRIMARY KEY \((.*)\)$`)
	rePgIndex  = regexp.MustCompile(`^CREATE (UNIQUE )?INDEX (\w+) ON (\w+) \((.*)\);$`)
)

// parsePostgres reads the statements tools/schemagen writes.
func parsePostgres(sql string) ([]Table, error) {
	var tables []Table
	byName := map[string]int{}
	var t *Table
	var create []string
	for _, line := range strings.Split(sql, "\n") {
		if m := rePgCreate.FindStringSubmatch(line); m != nil {
			byName[strings.ToLower(m[1])] = len(tables)
			tables = append(tables, Table{Name: m[1]})
			t, create = &tables[len(tables)-1], []string{line}
			continue
		}
		if m := rePgIndex.FindStringSubmatch(line); m != nil {
			i, ok := byName[strings.ToLower(m[3])]
			if !ok {
				return nil, fmt.Errorf("schema: index %s on unknown table %s", m[2], m[3])
			}
			tables[i].Indexes = append(tables[i].Indexes, Index{Name: strings.ToLower(m[2]), Unique: m[1] != "",
				Columns: splitList(m[4]), Def: strings.TrimSuffix(line, ";")})
			continue
		}
		if t == nil {
			continue
		}
		create = append(create, line)
		if line == ");" {
			t.Create = strings.TrimSuffix(strings.Join(create, "\n"), ";")
			t = nil
			continue
		}
		if m := rePgPK.FindStringSubmatch(line); m != nil {
			t.Indexes = append(t.Indexes, Index{Name: strings.ToLower(t.Name) + "_pkey", Primary: true, Unique: true, Columns: splitList(m[1])})
			continue
		}
		c := rePgCol.FindStringSubmatch(line)
		if c == nil {
			return nil, fmt.Errorf("schema: table %s: cannot parse %q", t.Name, line)
		}
		t.Columns = append(t.Columns, Column{Name: c[1], Def: c[2]})
	}
	if t != nil {
		return nil, fmt.Errorf("schema: table %s is not closed", t.Name)
	}
	return tables, nil
}

func splitList(s string) []string {
	var out []string
	for _, p := range strings.Split(s, ",") {
		out = append(out, strings.TrimSpace(p))
	}
	return out
}
